schuldrechtliche_sondergrundfrist <- function(fristfall = NULL, ereignis_am = NULL, einordnungsnachweis = NULL) {
  faelle <- list(
    hinterlegungsanzeige = list(30, "jahre", "\u00a7382: Empfang der Hinterlegungsanzeige; Meldung des Gl\u00e4ubigers und Erl\u00f6schenswirkung nicht gepr\u00fcft."),
    hypothekenschuld_mitteilung = list(6, "monate", "\u00a7416: Empfang der qualifizierten Mitteilung des Ver\u00e4u\u00dferers nach Eintragung; Textform und Hinweis sowie ausbleibende Verweigerung gesondert."),
    wiederkauf_grundstueck = list(30, "jahre", "\u00a7462: Vereinbarung des Wiederkaufsvorbehalts f\u00fcr ein Grundst\u00fcck; nur ohne abweichend bestimmte Aus\u00fcbungsfrist."),
    wiederkauf_sonstiger_gegenstand = list(3, "jahre", "\u00a7462: Vereinbarung des Wiederkaufsvorbehalts f\u00fcr anderen Gegenstand; nur ohne abweichend bestimmte Aus\u00fcbungsfrist."),
    vorkauf_grundstueck = list(2, "monate", "\u00a7469: Empfang der vollst\u00e4ndigen qualifizierten Mitteilung des Drittkaufs f\u00fcr Grundst\u00fcck; nur gesetzliche Frist ohne abweichende Bestimmung."),
    vorkauf_sonstiger_gegenstand = list(1, "wochen", "\u00a7469: Empfang der vollst\u00e4ndigen qualifizierten Mitteilung des Drittkaufs f\u00fcr anderen Gegenstand; nur gesetzliche Frist ohne abweichende Bestimmung."),
    verbrauchsgut_uebergabe = list(30, "tage", "\u00a7475 Absatz1: Vertragsschluss bei weder bestimmter noch aus Umst\u00e4nden entnehmbarer Leistungszeit; sp\u00e4teste \u00dcbergabe, kein allgemeiner Anspruch auf Ausnutzung von30Tagen statt unverz\u00fcglich."),
    behandlungsakte_aufbewahrung = list(10, "jahre", "\u00a7630f Absatz3: Abschluss der Behandlung; nur BGB-Grunddauer, andere Aufbewahrungsfristen k\u00f6nnen vorgehen. Keine automatische L\u00f6schfreigabe."),
    bauaenderung_einigung = list(30, "tage", "\u00a7650b Absatz2: Zugang des \u00c4nderungsbegehrens; Einigung und sonstige Anordnungsvoraussetzungen separat. Anordnung erst nach erfolglosem Ablauf, nicht bereits am Beginn des Endtags."),
    bauschlussrechnung_einwendungen = list(30, "tage", "\u00a7650g Absatz4: Zugang der Schlussrechnung; begr\u00fcndete Einwendungen/Pr\u00fcff\u00e4higkeit und Abnahme gesondert, kein automatischer F\u00e4lligkeitsentscheid."),
    mietfortsetzung_vermieter_545 = list(2, "wochen", "\u00a7545: Kenntnis des Vermieters vom Fortgebrauch nach Mietende. Nur Grundfrist f\u00fcr dessen entgegenstehenden Willen, kein automatischer Fortsetzungsentscheid."),
    mietformmangel_mindestbindung_550 = list(1, "jahre", "\u00a7550: Tats\u00e4chliche \u00dcberlassung des Wohnraums im qualifizierten Schriftformmangelfall bei Vertragsdauer \u00fcber einem Jahr. Fr\u00fcheste Jahresgrenze; K\u00fcndigungsfrist/Termin gesondert."),
    miete_eintrittsablehnung_563 = list(1, "monate", "\u00a7563III: Kenntnis der konkret eingetretenen Person vom Tod des Mieters. Grundfrist; entsprechend210 n\u00f6tige Ablaufhemmung gesondert."),
    miete_vermieter_eintrittskuendigung_563 = list(1, "monate", "\u00a7563IV: Kenntnis des Vermieters vom endg\u00fcltigen Eintritt. Wichtiger Grund und zus\u00e4tzliche gesetzliche K\u00fcndigungsfrist gesondert."),
    miete_ueberlebende_mieter_563a = list(1, "monate", "\u00a7563aII: Kenntnis des \u00fcberlebenden Mitmieters vom Tod. Erkl\u00e4rungsgrundfrist, nicht Beendigungstermin."),
    miete_erbenfortsetzung_564 = list(1, "monate", "\u00a7564: Kenntnis sowohl vom Tod als auch davon, dass weder Eintritt noch Fortsetzung erfolgt sind. Ma\u00dfgebliches Ereignis ist das Vorliegen beider Kenntnisse; gesetzliche K\u00fcndigungsfrist zus\u00e4tzlich."),
    miete_todesfallkuendigung_580 = list(1, "monate", "\u00a7580: Kenntnis des jeweils k\u00fcndigenden Erben oder Vermieters vom Tod. Anwendungsbereich qualifiziert; gesetzliche K\u00fcndigungsfrist zus\u00e4tzlich."),
    architekten_unterlagenkuendigung_650r = list(2, "wochen", "\u00a7650rI: Vorlage der Unterlagen nach650pII; bei Verbraucher nur mit rechtzeitiger vollst\u00e4ndiger Unterrichtung in Textform. Ohne diese Voraussetzung keine Anwendung dieser Grundfrist."),
    zahlungsinstrument_anzeigenachweis_675m = list(18, "monate", "\u00a7675mI2: Anzeige des Verlusts/Diebstahls/Missbrauchs oder sonstiger nicht autorisierter Nutzung. Mindestende der Bereitstellung von Nachweismitteln, keine L\u00f6schfreigabe."),
    zahlungsvorgang_anzeige_676b = list(13, "monate", "\u00a7676bII/IV: Belastungstag bei bereits ordnungsgem\u00e4\u00dfer Information; sonst sp\u00e4terer Tag der erforderlichen Unterrichtung. Unverz\u00fcglichkeit, unverschuldete Verhinderung und \u00fcbrige Anspruchsvoraussetzungen gesondert."),
    mieterpfand_entfernung_562b = list(1, "monate", "\u00a7562bII: Kenntnis des Vermieters von der qualifizierten Entfernung. Gerichtliche Geltendmachung und Erl\u00f6schen gesondert; keine automatische Rechtsfolge."),
    miete_schonfrist_569 = list(2, "monate", "\u00a7569III2 beziehungsweiseIIa: Eintritt der Rechtsh\u00e4ngigkeit des R\u00e4umungsanspruchs. Nur Grundfrist; vollst\u00e4ndige Befriedigung/\u00f6ffentliche Verpflichtung und Zweijahreswiederholung gesondert."),
    miete_erhoehungsurteil_wartefrist_569 = list(2, "monate", "\u00a7569III3: Rechtskraft der Verurteilung zur erh\u00f6hten Miete. Wartefristende, keine K\u00fcndigung schon zu Beginn dieses Endtags; Ausnahme wegen bisher geschuldeter Miete gesondert."),
    zeitmiete_befristungsauskunft_575 = list(1, "monate", "\u00a7575II: Zugang eines rechtzeitig qualifizierten Auskunftsverlangens. Fr\u00fchester Verlangenszeitpunkt und Verl\u00e4ngerung bei versp\u00e4teter Antwort separat."),
    landpacht_anfangsbeschreibung_585b = list(9, "monate", "\u00a7585bII: \u00dcberlassung der Pachtsache; Grundgrenze f\u00fcr Sachverst\u00e4ndigenbeschreibung, kein Verstreichen von mehr als neun Monaten am Endtag selbst. Voraussetzungen und h\u00e4lftige Kosten separat."),
    landpacht_endbeschreibung_585b = list(3, "monate", "\u00a7585bII: Beendigung des Pachtverh\u00e4ltnisses; Grundgrenze f\u00fcr Sachverst\u00e4ndigenbeschreibung, kein Verstreichen von mehr als drei Monaten am Endtag selbst. Voraussetzungen und Kosten separat."),
    landpacht_fortsetzungsablehnung_594 = list(3, "monate", "\u00a7594: Zugang einer wirksamen schriftlichen Anfrage mit Folgenhinweis im drittletzten Pachtjahr bei mindestens dreij\u00e4hrigem Vertrag. Nur Ablehnungsgrundfrist, keine automatische Verl\u00e4ngerungsentscheidung."),
    landpacht_todesfallerklaerung_594d = list(1, "monate", "\u00a7594dI: Kenntnis vom Tod des P\u00e4chters beim jeweils Erkl\u00e4renden. K\u00fcndigungserkl\u00e4rungsfrist; zus\u00e4tzliche sechs Monate zum Quartalsende und Erbenwiderspruch separat."),
    betriebsuebergang_widerspruch_613a = list(1, "monate", "\u00a7613aVI: Zugang vollst\u00e4ndiger rechtlich ordnungsgem\u00e4\u00dfer Unterrichtung nachAbsatz5. Bei mangelhafter Unterrichtung nicht durch blo\u00dfes Zugangsdatum ersetzen."),
    pauschalreise_rueckerstattung_651h = list(14, "tage", "\u00a7651hV: rechtlich wirksamer R\u00fccktritt. \u00c4u\u00dferste R\u00fcckerstattungsgrundfrist; unverz\u00fcgliche Leistungspflicht besteht daneben, kein allgemeines Recht zum Abwarten von14Tagen."),
    darlehen_unbestimmte_rueckzahlung_488 = list(3, "monate", "\u00a7488III: Zugang wirksamer K\u00fcndigung bei nicht bestimmter R\u00fcckzahlungszeit. Anwendungsbereich und zinslose R\u00fcckzahlung ohne K\u00fcndigung gesondert."),
    darlehen_variabler_zins_489 = list(3, "monate", "\u00a7489II: Zugang wirksamer Darlehensnehmerk\u00fcndigung bei ver\u00e4nderlichem Zinssatz. R\u00fcckzahlungserfordernisAbsatz3 und SonderausnahmenAbsatz4/5 gesondert."),
    frueherer_gebaeudebesitzer_836 = list(1, "jahre", "\u00a7836II: Beendigung des Eigenbesitzes. Nur rechnerisches einj\u00e4hriges Ereignisfenster f\u00fcr Einsturz/Abl\u00f6sung; Verschulden, Sorgfaltseinwendungen, Kausalit\u00e4t und Schaden separat."),
    zahlung_erstattungsverlangen_675x = list(8, "wochen", "\u00a7675xIV: Belastung des betreffenden Zahlungsbetrags, taggenau qualifiziert. Ausschlussgrundfrist f\u00fcr Erstattungsverlangen; Anspruchsvoraussetzungen und abweichendes Sonderrecht675xVI separat."),
    urlaubslangprodukt_kuendigung_486a = list(2, "wochen", "\u00a7486aII: Zugang der qualifizierten Zahlungsaufforderung ab dem vorgesehenen zweiten Teilbetrag. Erkl\u00e4rungsgrundfrist; K\u00fcndigungswirkung zum F\u00e4lligkeitstermin und mindestens zweiw\u00f6chiger Vorlauf486aI gesondert."),
    landpacht_fortsetzungsverlangen_kurzfrist_595 = list(1, "monate", "\u00a7595V2: Zugang der K\u00fcndigung bei vereinbarter K\u00fcndigungsfrist von h\u00f6chstens zw\u00f6lf Monaten. Grundfrist f\u00fcr Fortsetzungsverlangen; \u00fcbrige Voraussetzungen und gerichtlicher Antrag gesondert."),
    landpacht_gerichtsantrag_kurzfrist_595 = list(2, "monate", "\u00a7595VII: Zugang der K\u00fcndigung bei h\u00f6chstens zw\u00f6lfmonatiger K\u00fcndigungsfrist. Grundfrist f\u00fcr Gerichtsantrag; m\u00f6gliche nachtr\u00e4gliche Zulassung und noch nicht abgelaufener Vertrag gesondert."),
    miete_ausgleichszahlung_auskunft_558 = list(1, "monate", "\u00a7558IV: Zugang eines rechtzeitig zul\u00e4ssigen Auskunftsverlangens \u00fcber Ausgleichszahlung. Grundfrist f\u00fcr Antwort; fr\u00fchester Anfragezeitpunkt vier Monate vor Bindungsende und Erh\u00f6hungsprivileg separat."),
    gesellschaft_erbenrechtsausuebung_724 = list(3, "monate", "\u00a7724III: Kenntnis vom Erbschaftsanfall. Nur Dreimonatsgrundfrist; entsprechend210 n\u00f6tige Ablaufhemmung und noch offene Ausschlagungsfrist k\u00f6nnen das Ende verl\u00e4ngern und sind ausdr\u00fccklich zus\u00e4tzlich zu berechnen."),
    gesellschaft_volljaehrigenkuendigung_725 = list(3, "monate", "\u00a7725IV: ma\u00dfgeblicher Beginn nach Vollj\u00e4hrigkeit und Kenntnis oder Kennenm\u00fcssen der Gesellschafterstellung. Bei vorangegangener Kenntnis fr\u00fchestens Vollj\u00e4hrigkeit; rechtlich qualifizierten Beginn eingeben. Ausnahmen112/Befriedigung pers\u00f6nlicher Bed\u00fcrfnisse und Wirksamkeit gesondert."),
    widerruf_verbraucher_rueckgewaehr_357 = list(14, "tage", "\u00a7355III/357I, gegebenenfalls357d: Abgabe der Widerrufserkl\u00e4rung durch Verbraucher. \u00c4u\u00dferste R\u00fcckgew\u00e4hrgrundfrist im qualifizierten357-Fall, daneben unverz\u00fcglich; rechtzeitige Warenabsendung kann Frist wahren, Abholangebot und R\u00fccksendekosten separat."),
    widerruf_unternehmer_rueckgewaehr_357 = list(14, "tage", "\u00a7355III/357I: Zugang der Widerrufserkl\u00e4rung beim Unternehmer, nicht deren fr\u00fchere Abgabe. \u00c4u\u00dferste R\u00fcckgew\u00e4hrgrundfrist; daneben unverz\u00fcglich, m\u00f6gliches Verweigerungsrecht357IV und weitere R\u00fcckgew\u00e4hrfolgen separat."),
    finanzwiderruf_verbraucher_rueckgewaehr_357b = list(30, "tage", "\u00a7355III/357bI: Abgabe der Widerrufserkl\u00e4rung durch Verbraucher im qualifizierten357b-Fall. \u00c4u\u00dferste R\u00fcckgew\u00e4hrgrundfrist von30Kalendertagen, kein pauschaler Kalendermonat; Zinsen/Wertersatz separat."),
    finanzwiderruf_unternehmer_rueckgewaehr_357b = list(30, "tage", "\u00a7355III/357bI: Zugang der Widerrufserkl\u00e4rung beim Unternehmer im qualifizierten357b-Fall. \u00c4u\u00dferste R\u00fcckgew\u00e4hrgrundfrist von30Kalendertagen; nicht Abgabe des Verbrauchers. Unverz\u00fcglichkeit und sonstige Anspr\u00fcche separat."),
    darlehen_vorzeitige_kuendigung_wartefrist_490 = list(6, "monate", "\u00a7490II: Tag des vollst\u00e4ndigen Empfangs des Darlehens. Sechsmonatswartefrist endet mit Ablauf des berechneten Tages; K\u00fcndigung danach, fr\u00fchestens am Folgetag. Nur Wartefrist, nicht bereits K\u00fcndigungswirkung. Dreimonatige K\u00fcndigungsfrist488III2 gesondert ab wirksamer Erkl\u00e4rung/Zugang berechnen. Gebundener Sollzins, Grund-/Schiffspfandrecht, berechtigtes Interesse und rechtliche Anwendbarkeit vorqualifizieren; keine automatische Vorf\u00e4lligkeitsentsch\u00e4digung."),
    miete_dreissigjahreswartefrist_544 = list(30, "jahre", "\u00a7544: Tag der tats\u00e4chlichen \u00dcberlassung der Mietsache, nicht allein Vertragsschluss. Drei\u00dfigjahreswartefrist endet mit Ablauf des berechneten Tages; Erkl\u00e4rung danach, fr\u00fchestens am Folgetag. Qualifizierter Vertrag f\u00fcr l\u00e4nger als30Jahre, keine Lebenszeitvereinbarung. Gesetzliche K\u00fcndigungsfrist und konkreter Beendigungstermin zus\u00e4tzlich berechnen; keine automatische Vertragsbeendigung am Grenztag."),
    darlehen_vorzeitige_kuendigungsfrist_490 = list(3, "monate", "\u00a7490II in Verbindung mit488III2: Zugang der wirksamen vorzeitigen K\u00fcndigung nach bereits abgelaufener Sechsmonatswartefrist seit vollst\u00e4ndigem Darlehensempfang. Dreimonatige Grundfrist; Vorliegen des qualifizierten K\u00fcndigungsgrundes und Wirksamkeit der Erkl\u00e4rung gesondert. Nicht automatisch ab Empfang oder Ablauf der Wartefrist rechnen."),
    schuldverschreibung_zahlungssperre_802 = list(6, "monate", "\u00a7802Satz2: Beseitigung des der Einleitung entgegenstehenden Hindernisses. Nur sechsmonatige Grundfrist bei Zahlungssperre vor Verfahrenseinleitung und ohne vorherigen Einleitungsantrag.206/210/211-Korrekturen ausdr\u00fccklich separat; tats\u00e4chliche Verfahrenserledigung und Antragsdaten separat f\u00fcr Hemmungsintervall bestimmen."),
    anteilschein_verlustanspruch_804 = list(4, "jahre", "\u00a7804I3/200: Entstehung des rechtlich qualifizierten Verlustanspruchs nach Ablauf der Vorlegungsfrist; nicht bereits Verlust oder Verlustanzeige. Vierj\u00e4hrige taggenaue Grundverj\u00e4hrung, kein automatischer Jahresendbeginn. Rechtzeitige Verlustanzeige, fehlender Anspruchsausschluss und ma\u00dfgeblicher Entstehungstag vorqualifiziert. Hemmung/Ablaufhemmung/Neubeginn gesondert."))
  .auswahl(fristfall, "fristfall", names(faelle))
  .datum(ereignis_am, "ereignis_am")
  .text(einordnungsnachweis, "einordnungsnachweis")
  fall <- faelle[[fristfall]]
  ende <- .frist(ereignis_am, fall[[1]], fall[[2]], "ereignis")
  eingaben <- list(fristfall = fristfall, ereignis_am = ereignis_am, einordnungsnachweis = einordnungsnachweis)
  ergebnis <- .ergebnis(list(rechnerisches_fristende = .iso(ende)), "datum", "BGB_SCHULDRECHTLICHE_SONDERGRUNDFRIST", eingaben,
    list(list(operation = "Gesetzliche Dauer nach Fristfall ausw\u00e4hlen und Ereignisfrist mit vorhandenem Kalenderkern berechnen")), eingaben)
  ergebnis$annahmen <- list("Rechtlich ma\u00dfgeblicher Fristfall und Ereignistag sowie ausschlie\u00dfliche Anwendung der gesetzlichen Standarddauer qualifiziert; feste lokale BGB-Fassung.")
  ergebnis$hinweise <- list("Nur rechnerische gesetzliche Grundfrist mit Ereignisbeginn; keine automatische Feiertags-/Hemmungs-/sonstige Fristkorrektur. Fristende bezeichnet den letzten eingeschlossenen Tag bis Tagesablauf; rechtzeitige Handlungen am Endtag bleiben m\u00f6glich. Qualifizierte Normvoraussetzungen und abweichende Sonderregeln vor Nutzung bestimmen.", fall[[3]])
  ergebnis
}
